#include <stdio.h>
#include <string.h>
void reverse(char* s){
  int i=0, j=strlen(s)-1;
  while(i<j){
    char t=s[i]; s[i]=s[j]; s[j]=t;
    i++; j--;
  }
}
int main(){
  char str[] = "hello";
  reverse(str);
  printf("%s", str);
}

#include <stdio.h>

struct point { int x; int y; };

void swap(struct point* a, struct point* b) {
    struct point t = *a;
    *a = *b;
    *b = t;
}

int main() {
    struct point arr[3] = {{1,2},{3,4},{5,6}};
    swap(&arr[0], &arr[2]);
    printf("%d 그리고 %d", arr[0].x, arr[2].y);
    return 0;
}

